with exploded as (select id, customer_id, created_at, coupon_codes, inline(items) from carts), scored as (select coupon_codes, product_id, qty, count(price) over (partition by promo order by cast(created_at as bigint) range between 3600 preceding and current row) as price_count_1h, dense_rank() over (partition by customer_id order by price nulls last) as price_dense_rank, stddev_samp(product_id) over (partition by customer_id, promo) as customer_id_stddev_samp_product_id from exploded), valid as (select coupon_codes, qty, price_dense_rank, customer_id_stddev_samp_product_id, round(qty / price_count_1h, 2) as qty_per_price_count_1h from scored where customer_id_stddev_samp_product_id = 4), valid_carts as (select *, cast(qty as string) as qty_num from valid where customer_id_stddev_samp_product_id > 6) select customer_id_stddev_samp_product_id, sum(customer_id_stddev_samp_product_id) as total_customer_id_stddev_samp_product_id, percentile_approx(price_dense_rank, array(0.25, 0.5, 0.75)) as price_dense_rank_quartiles from valid_carts group by customer_id_stddev_samp_product_id;
